package test;

import java.io.InputStream;
import java.io.OutputStream;
import java.io.IOException;

// Mock interfaces/classes for example compilation
interface IProgressMonitor {
    void worked(int i);
    IProgressMonitor split(int i);
}

class SubMonitor implements IProgressMonitor {
    public static SubMonitor convert(IProgressMonitor monitor, int totalWork) { return new SubMonitor(); }
    public void worked(int i) {}
    public IProgressMonitor split(int i) { return new SubMonitor(); }
}

class MyCoreException extends Exception {
    public MyCoreException(String message, Throwable cause) { super(message, cause); }
}

// Dummy FileUtil class representing the old API
class FileUtil {
    public static void transferStreams(InputStream source, OutputStream destination, String path, IProgressMonitor monitor) throws MyCoreException {
        // Simulate transfer logic
        SubMonitor subMonitor = SubMonitor.convert(monitor, 1);
        try {
            byte[] buffer = new byte[8192];
            int bytesRead;
            while ((bytesRead = source.read(buffer)) != -1) {
                destination.write(buffer, 0, bytesRead);
                subMonitor.worked(1);
            }
        } catch (IOException e) {
            throw new MyCoreException("Failed to transfer", e);
        }
    }
}

public class MyStreamProcessor {
    public void process(InputStream content, OutputStream out, String storeName, IProgressMonitor monitor) throws MyCoreException, IOException {
        SubMonitor subMonitor = SubMonitor.convert(monitor, 100);
        try (content; out) {
            // Old API call
            FileUtil.transferStreams(content, out, storeName, subMonitor.split(1));
            subMonitor.worked(95);
        }
    }
}

